CREATE TABLE public.benefits_catalogue (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  key text NOT NULL UNIQUE,
  sort_order integer NOT NULL DEFAULT 0,
  name text NOT NULL,
  german text NOT NULL,
  summary text NOT NULL,
  monthly text,
  category text NOT NULL,
  authority text NOT NULL,
  eligible_if text[] NOT NULL DEFAULT '{}',
  payload jsonb NOT NULL DEFAULT '{}'::jsonb,
  apply_url text,
  notes text,
  active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

GRANT SELECT ON public.benefits_catalogue TO anon, authenticated;
GRANT ALL ON public.benefits_catalogue TO service_role;

ALTER TABLE public.benefits_catalogue ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Benefits catalogue is public read" ON public.benefits_catalogue
  FOR SELECT TO anon, authenticated USING (active = true);

CREATE POLICY "Admins manage benefits catalogue" ON public.benefits_catalogue
  FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin'))
  WITH CHECK (public.has_role(auth.uid(),'admin'));

CREATE TRIGGER update_benefits_catalogue_updated_at
  BEFORE UPDATE ON public.benefits_catalogue
  FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();

